import type { NotionPageId } from "@notionhq/custom-blocks-protocol/ids.js"
import type { InitMessage } from "@notionhq/custom-blocks-protocol/messages/init.js"
import type {
	CreatePageArgs,
	CreatePageResult,
	GetPageResult,
	GetUserResult,
	ListUsersArgs,
	ListUsersResult,
	NotionUserId,
	UpdatePageArgs,
	UpdatePageResult,
} from "../types.js"
import {
	type CustomBlockHostState,
	type DataSourceQueryView,
	getDataSourceQueryView as getDataSourceQueryViewWithBridge,
} from "./hostState.js"
import type { ManifestLoadResult } from "./loadManifest.js"
import {
	type MessageLogEntry,
	type QueryDataSourceArgs,
	SandboxBridge,
} from "./SandboxBridge.js"

let bridge: SandboxBridge | undefined
let didWarnAboutPagesDelete = false

function getBridge(): SandboxBridge {
	if (!bridge) {
		bridge = new SandboxBridge()
	}
	return bridge
}

export const customBlockHost = {
	start: () => {
		getBridge().startListening()
	},

	sendConnect: (manifestResult: ManifestLoadResult) => {
		getBridge().sendConnect(manifestResult)
	},

	awaitInit: (): Promise<void> => {
		return getBridge().awaitInit()
	},

	subscribe: (listener: () => void) => {
		return getBridge().subscribe(listener)
	},

	getState: (): CustomBlockHostState => {
		return getBridge().getHostState()
	},

	/**
	 * Apply an `init` payload directly, bypassing the postMessage handshake for
	 * standalone preview state.
	 */
	setMockState: (message: InitMessage) => {
		getBridge().setMockState(message)
	},

	completeInitialization: () => {
		getBridge().completeInitialization()
	},

	postResize: (height: number) => {
		getBridge().postResize(height)
	},
}

export const customBlockDataSources = {
	createSubscriptionId: () => {
		return getBridge().createDataSourceSubscriptionId()
	},

	query: (args: QueryDataSourceArgs) => {
		getBridge().queryDataSource(args)
	},

	release: (subscriptionId: string) => {
		getBridge().releaseDataSourceSubscription(subscriptionId)
	},

	getView: (
		hostState: CustomBlockHostState,
		key: string,
		subscriptionId: string,
	): DataSourceQueryView => {
		return getDataSourceQueryViewWithBridge(
			hostState,
			key,
			subscriptionId,
			args => getBridge().updateDataSourcePage(args),
		)
	},
}

export const messageLog = {
	getSnapshot: (): readonly MessageLogEntry[] => {
		return getBridge().getMessageLog()
	},

	subscribe: (listener: () => void) => {
		return getBridge().subscribeToMessageLog(listener)
	},
}

/**
 * Page-related SDK APIs exposed under `sdk.pages.*`.
 */
export const pages = {
	/**
	 * Creates a new Notion page.
	 */
	create: (input: CreatePageArgs): Promise<CreatePageResult> => {
		return getBridge().createPage(input)
	},

	/**
	 * Fetches a page by id.
	 */
	get: (pageId: NotionPageId): Promise<GetPageResult> => {
		return getBridge().getPage(pageId)
	},

	/**
	 * Updates an existing page.
	 */
	update: (input: UpdatePageArgs): Promise<UpdatePageResult> => {
		return getBridge().updatePage(input)
	},

	/**
	 * Archives a page.
	 */
	archive: (pageId: NotionPageId): Promise<UpdatePageResult> => {
		return getBridge().updatePage({ pageId, is_archived: true })
	},

	/**
	 * Unarchives a page.
	 */
	unarchive: (pageId: NotionPageId): Promise<UpdatePageResult> => {
		return getBridge().updatePage({ pageId, is_archived: false })
	},

	/**
	 * @deprecated This method archives the page. It does not move the page to Trash.
	 * Use `pages.archive(pageId)` instead.
	 */
	delete: (pageId: NotionPageId): Promise<UpdatePageResult> => {
		if (!didWarnAboutPagesDelete) {
			didWarnAboutPagesDelete = true
			console.warn(
				"[Notion Custom Blocks] DEPRECATED: pages.delete() archives the page. It does not move the page to Trash. Use pages.archive() instead.",
			)
		}
		return getBridge().updatePage({ pageId, is_archived: true })
	},
}

/**
 * User-related SDK APIs exposed under `sdk.users.*`.
 */
export const users = {
	/**
	 * Lists users visible in the current custom block workspace.
	 */
	list: (input?: ListUsersArgs): Promise<ListUsersResult> => {
		return getBridge().listUsers(input)
	},

	/**
	 * Fetches a user by id.
	 */
	get: (userId: NotionUserId): Promise<GetUserResult> => {
		return getBridge().getUser(userId)
	},
}
